              <td>{{ m.name }}</td>
              <td><button type="button" (click)="onEdit(m)">Edit</button></td>
              <td><button type="button" (click)="onDelete(m)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>
    @if (editing(); as e) {
      <app-edit-manufacturer [manufacturer]="e" (saved)="onSaved($event)" (closed)="editing.set(null)"></app-edit-manufacturer>
    }`,
})
export class ManufacturerComponent implements OnInit {
  private api = inject(ApiService);
  private messages = inject(MessageService);

  readonly manufacturers = signal<ManufacturerDto[]>([]);
  readonly editing = signal<ManufacturerDto | null>(null);
  private editingOriginal: ManufacturerDto | null = null;

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({ next: (l) => this.manufacturers.set(l ?? []), error: (e) => this.messages.error(e) });
  }

  onCreate(): void {
    this.editingOriginal = null;
    this.editing.set({ name: '', cars: [] });
  }

  onEdit(m: ManufacturerDto): void {
    this.editingOriginal = m;
    this.editing.set({ ...m });
  }

  onDelete(m: ManufacturerDto): void {
    if (!window.confirm(`Are you sure you want to delete ${m.name}?`)) return;
    this.api.deleteManufacturer(m.id as number).subscribe({
      next: () => this.manufacturers.update((l) => l.filter((x) => x !== m)),
      error: (e) => this.messages.error(e),
    });
  }

  onSaved(saved: ManufacturerDto): void {
    const old = this.editingOriginal;
    this.manufacturers.update((l) => {
      const i = old ? l.indexOf(old) : -1;
      return i >= 0 ? l.map((x, j) => (j === i ? saved : x)) : [...l, saved];
    });
    this.editingOriginal = saved;
    this.editing.set(null);
  }
}
