      next: (l) => { const cars = l ?? []; this.car = cars[0] ?? null; this.cars.set(cars); },
      error: (e) => { this.messages.error(e); this.closed.emit(); },
    });
  }

  onSave(): void {
    const text = String(this.rating ?? '').trim();
    const value = text === '' ? null : Number(text);
    if (value !== null && !Number.isInteger(value)) {
      this.messages.error(new Error(`"${text}" is not a valid number.`));
      return;
    }
    this.saving = true;
    this.api.saveRating({ rating: value, car: this.car }).subscribe({
      next: (r) => {
        this.saving = false;
        this.messages.success('The rating has been saved.');
        this.saved.emit(r);
      },
      error: (e) => { this.saving = false; this.messages.error(e); },
    });
  }
}
