const WebSocket = require('/work/node_modules/ws');
const { spawn } = require('child_process');
const http = require('http');
const chrome = spawn(process.env.CHROME_BIN || 'chromium', ['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9333','about:blank']);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const getJson = u => new Promise((res, rej) => http.get(u, r => { let d=''; r.on('data', c=>d+=c); r.on('end', ()=>res(JSON.parse(d))); }).on('error', rej));
(async () => {
  let tabs; for (let i=0;i<50;i++){ try { tabs = await getJson('http://127.0.0.1:9333/json'); break; } catch { await sleep(200);} }
  const ws = new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
  await new Promise(r=>ws.on('open',r));
  let id=0; const pend={};
  ws.on('message', m => { const d=JSON.parse(m); if(d.id&&pend[d.id]){pend[d.id](d);delete pend[d.id];} if(d.method==='Runtime.exceptionThrown'||(d.method==='Runtime.consoleAPICalled'&&d.params.type==='error')) console.log('PAGE ERR', JSON.stringify(d.params).slice(0,300)); });
  const send=(method,params={})=>new Promise(r=>{const i=++id;pend[i]=r;ws.send(JSON.stringify({id:i,method,params}));});
  await send('Runtime.enable');
  const ev = async (expr) => { const r = await send('Runtime.evaluate',{expression:`(async()=>{${expr}})()`,awaitPromise:true,returnByValue:true}); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0,400)); return r.result.result.value; };
  const helpers = `
    const $=s=>document.querySelector(s); const sl=ms=>new Promise(r=>setTimeout(r,ms));
