import { Injectable } from '@angular/core';
import { HashLocationStrategy } from '@angular/common';

/**
 * Hash routing with GWT-style history tokens: URLs look like `#manufacturer`
 * (as GWT's PlaceManager produces) instead of Angular's default `#/manufacturer`.
 * Both forms are accepted on input.
 */
@Injectable()
export class GwtHashLocationStrategy extends HashLocationStrategy {
  override path(includeHash = false): string {
    const p = super.path(includeHash);
    return p === '' || p.startsWith('/') ? p : '/' + p;
  }

  override prepareExternalUrl(internal: string): string {
    const url = super.prepareExternalUrl(internal);
    return url.replace('#/', '#');
  }
}
EOF
